mapper.select:
select po.* from Portfolio_Hdr po, UserPortfolioMap up 
where po.portfolio=up.portfolio and po.portfolioClient=#{clientCode} and up.userid=#{userid} 

	 and po.portfolioType=#{portType}


	  and (po.portName=#{portName} or po.shortName=#{portName} or po.shortCode=#{portName})

 order by po.portfolio asc

select * from Portfolio_Hdr where portfolioClient=#{clientCode}

	and portfolioType=#{portType}


	and (portName=#{portName} or shortName=#{portName} or shortCode=#{portName})

	order by id asc
